pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 preBalance, address user) public {
        // restrict deposits to non-zero to avoid trivial case, keep domain wide
        vm.assume(depositAmount > 0);
        // restrict preBalance to avoid overflow into zero in reference (reference cannot overflow)
        vm.assume(preBalance <= type(uint256).max - depositAmount);
        vm.assume(user != address(0));

        // set up pre-state: set user balance and provide ETH
        vm.deal(user, depositAmount);

        // directly manipulate storage via a wrapper is not allowed, so we deposit to reach preBalance
        // if preBalance > 0, we need to deposit first; provide funds again
        if (preBalance > 0) {
            vm.deal(user, preBalance + depositAmount);
            vm.prank(user);
            c.addToBalance{value: preBalance}();
        }

        uint256 balanceBefore = c.getBalance(user);
        require(balanceBefore == preBalance, "setup failed");

        vm.prank(user);
        c.addToBalance{value: depositAmount}();

        uint256 balanceAfter = c.getBalance(user);

        // invariant: if balanceBefore > 0, then balanceAfter should also be > 0
        // reference add_uint256 reverts on overflow, so positive balance never becomes zero
        // mutant unchecked addition can overflow to exactly 0
        if (balanceBefore > 0) {
            assertTrue(balanceAfter > 0);
        } else {
            // if balanceBefore == 0, ensure behavior is same
            assertTrue(balanceAfter == depositAmount);
        }
    }
}

