contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 attackerDeposit) public {
        vm.assume(depositAmount > 0);
        vm.assume(attackerDeposit > 0);
        vm.assume(depositAmount < type(uint256).max / 2);
        vm.assume(attackerDeposit < type(uint256).max / 2);

        // Deploy attacker that will re-enter during withdrawBalance
        Attacker attacker = new Attacker(c);
        address attackerAddr = address(attacker);

        // Fund the attacker and deposit
        vm.deal(attackerAddr, attackerDeposit);
        vm.prank(attackerAddr);
        c.addToBalance{value: attackerDeposit}();

        // Fund a victim user and deposit
        address victim = address(0x12345);
        vm.deal(victim, depositAmount);
        vm.prank(victim);
        c.addToBalance{value: depositAmount}();

        // Record balances before withdrawal
        uint256 balanceAttackerBefore = c.getBalance(attackerAddr);
        uint256 balanceVictimBefore = c.getBalance(victim);
        uint256 contractBalanceBefore = address(c).balance;

        // Attacker triggers withdrawBalance, which re-enters addToBalance
        vm.prank(attackerAddr);
        attacker.attack();

        // Read actual balances after the re-entrant attack
        uint256 balanceAttackerAfter = c.getBalance(attackerAddr);
        uint256 balanceVictimAfter = c.getBalance(victim);
        uint256 contractBalanceAfter = address(c).balance;

        // General invariant: sum of all userBalances must equal the contract's Ether balance
        // (No other paths to add/remove Ether; addToBalance increases balance, withdrawBalance sets to 0 and sends Ether)
        // In the reference, this holds for all inputs; in the buggy version, reentrancy can cause the sum to mismatch.
        assertTrue(balanceAttackerAfter + balanceVictimAfter == contractBalanceAfter);
    }
}

