import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 reentrantDepositAmount) public {
        // Keep amounts within reasonable bounds to avoid overflow on fuzzer inputs while still covering the bug.
        depositAmount = bound(depositAmount, 1, 1e30);
        reentrantDepositAmount = bound(reentrantDepositAmount, 1, 1e30);

        // Deploy the reentrant attacker that calls back into addToBalance during withdrawal.
        Attacker attacker = new Attacker(c);
        address attackerAddr = address(attacker);

        // Give the attacker some initial ETH so it can deposit.
        vm.deal(attackerAddr, depositAmount + reentrantDepositAmount);

        // Record the contract's ETH balance before the operation.
        uint256 contractBalanceBefore = address(c).balance;

        // The attacker makes the first deposit, which triggers the attack.
        vm.prank(attackerAddr);
        attacker.attack{value: depositAmount}(reentrantDepositAmount);

        // After the call, the ETH balance of the contract MUST NOT be smaller than before.
        // Under the correct version the deposit increases the balance (or at least does not decrease it),
        // but the buggy version allows the reentrant withdraw to drain ETH while the attacker's own
        // deposit is not yet recorded, causing a net decrease of the contract's ETH balance.
        assertTrue(address(c).balance >= contractBalanceBefore);
    }
}

contract Attacker {
    C public target;
    bool private attacking;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 extraDeposit) external payable {
        // First deposit to set up a positive balance.
        target.addToBalance{value: msg.value}();
        // Now withdraw; during withdrawal the receive() callback fires.
        target.withdrawBalance();
    }

    receive() external payable {
        // Re-enter only once to avoid infinite recursion.
        if (!attacking) {
            attacking = true;
            // During withdrawal, the attacker calls addToBalance again.
            // The buggy version lacks nonReentrant, so this reentrant call succeeds.
            // msg.value is zero here; we simply call addToBalance with no ETH to show
            // that the reentrancy window exists and can be used to corrupt state.
            target.addToBalance();
            attacking = false;
        }
    }
}

