pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // bound to reasonable range
        depositAmount = bound(depositAmount, 0.001 ether, 100 ether);
        withdrawAmount = bound(withdrawAmount, 0.001 ether, 100 ether);

        address user = makeAddr("user");
        vm.deal(user, type(uint256).max);

        // deposit
        vm.prank(user);
        c.addToBalance{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;

        // withdraw
        vm.prank(user);
        if (withdrawAmount <= c.getBalance(user)) {
            c.withdrawBalance();
        }

        // invariant: contract's ETH balance decreases by exactly the user's withdrawn balance,
        // i.e., delta ETH = userBalance[user] (before withdrawal).
        // userBalance is now 0 after withdrawal, so delta should equal old userBalance.
        // The mutant fails because it sends only 1 wei regardless of the recorded userBalance.
        address payable target = payable(address(0xdead));
        // We cannot read private _locked, but we observe public side: getBalance(user) after withdrawal is 0.
        // The ETH delta equals old userBalance (which was c.getBalance(user) before withdrawal).
        // Old userBalance >= withdrawAmount by the if condition, though withdrawBalance always sends the full balance.
        // Actually withdrawBalance always sends the full recorded balance; the 'if' is a guard to prevent reverts from insufficient balance.
        // After a successful withdrawal: userBalance is cleared to 0, and the ETH transferred equals the recorded balance before.
        // For any withdraw that succeeds, the contract's ETH drops by exactly the old userBalance.
        uint256 oldBalance = c.getBalance(user);
        if (oldBalance > 0 && withdrawAmount <= oldBalance) {
            uint256 contractBefore = address(c).balance;
            vm.prank(user);
            c.withdrawBalance();
            uint256 contractAfter = address(c).balance;
            assertTrue(contractAfter == contractBefore - oldBalance);
        } else {
            // if withdrawal didn't happen (reverts or skipped), invariant trivially holds.
            assertTrue(true);
        }
    }
}

